#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn transient_errors_are_retryable() {
        assert!(RetryError::Transient("temporary".into()).is_transient());
        assert!(!RetryError::Permanent("invalid".into()).is_transient());
    }

    #[test]
    fn retries_with_bounded_exponential_delays() {
        let config = RetryConfig {
            max_attempts: 5,
            base_delay_ms: 10,
            max_delay_ms: 25,
        };
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("down".into()))
        });

        assert_eq!(calls, 5);
        assert_eq!(sleeper.sleeps, vec![10, 20, 25, 25]);
        assert_eq!(result, Err(RetryError::Transient("down".into())));
    }

    #[test]
    fn permanent_errors_do_not_retry_or_sleep() {
        let config = RetryConfig {
            max_attempts: 5,
            base_delay_ms: 10,
            max_delay_ms: 100,
        };
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            Err(RetryError::Permanent("bad input".into()))
        });

        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
        assert_eq!(result, Err(RetryError::Permanent("bad input".into())));
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn stops_after_success() {
        let config = RetryConfig {
            max_attempts: 4,
            base_delay_ms: 5,
            max_delay_ms: 20,
        };
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            if calls == 3 { Ok(()) } else { Err(RetryError::Transient("retry".into())) }
        });

        assert_eq!(result, Ok(()));
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![5, 10]);
    }

    #[test]
    fn zero_attempt_budget_still_makes_first_call() {
        let config = RetryConfig { max_attempts: 0, base_delay_ms: 1, max_delay_ms: 10 };
        let mut sleeper = FakeSleeper::default();
        let result = run_job(&config, &mut sleeper, || Err(RetryError::Transient("fail".into())));

        assert_eq!(result, Err(RetryError::Transient("fail".into())));
        assert_eq!(sleeper.sleeps, Vec::<u64>::new());
    }
}

