arguments.content:
mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    // A zero budget is treated defensively as one attempt.
    let max_attempts = config.max_attempts.max(1);
    let mut attempt = 0;
    let mut delay = config.base_delay_ms.min(config.max_delay_ms);

    loop {
        attempt += 1;
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() || attempt >= max_attempts => {
                return Err(error);
            }
            Err(_) => {
                sleeper.sleep_ms(delay);
                delay = delay.saturating_mul(2).min(config.max_delay_ms);
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn retries_with_bounded_exponential_delays() {
        let config = RetryConfig { max_attempts: 5, base_delay_ms: 10, max_delay_ms: 25 };
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("down".into()))
        });
        assert_eq!(calls, 5);
        assert_eq!(sleeper.sleeps, vec![10, 20, 25, 25]);
        assert_eq!(result, Err(RetryError::Transient("down".into())));
    }

    #[test]
    fn permanent_errors_return_immediately() {
        let config = RetryConfig { max_attempts: 5, base_delay_ms: 10, max_delay_ms: 100 };
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            Err(RetryError::Permanent("bad input".into()))
        });
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
        assert_eq!(result, Err(RetryError::Permanent("bad input".into())));
    }

    #[test]
    fn stops_after_success() {
        let config = RetryConfig { max_attempts: 4, base_delay_ms: 5, max_delay_ms: 20 };
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            if calls == 3 { Ok(()) } else { Err(RetryError::Transient("retry".into())) }
        });
        assert_eq!(result, Ok(()));
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![5, 10]);
    }
}

//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between attempts, in milliseconds.
    pub max_delay_ms: u64,
}

impl Default for RetryConfig {
    fn default() -> Self {
        Self { max_attempts: 1, base_delay_ms: 0, max_delay_ms: 0 }
    }
}

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn transient_failure_then_success_uses_one_delay_per_retry() {
    let config = RetryConfig { max_attempts: 3, base_delay_ms: 7, max_delay_ms: 20 };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        if calls == 2 { Ok(()) } else { Err(RetryError::Transient("temporary".into())) }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 2);
    assert_eq!(sleeper.sleeps, vec![7]);
}

